import heapq
class Solution:
    def minOperations(self, s1: str, s2: str, x: int) -> int:
        n = len(s1)
        start = sum(1 << i for i in range(n) if s1[i] != s2[i])
        if bin(start).count('1') % 2:
            return -1
        dist = {start: 0}
        pq = [(0, start)]
        while pq:
            c, m = heapq.heappop(pq)
            if m == 0:
                return c
            if c > dist.get(m, 1 << 60):
                continue
            for i in range(n):
                for j in range(i + 1, n):
                    nm = m ^ (1 << i) ^ (1 << j)
                    w = x if j > i + 1 else 1
                    if c + w < dist.get(nm, 1 << 60):
                        dist[nm] = c + w
                        heapq.heappush(pq, (c + w, nm))
        return -1

