#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    int minOperations(string s1, string s2, int x) {
        int n = s1.size();
        long long start = 0;
        for (int i = 0; i < n; i++) if (s1[i] != s2[i]) start |= 1LL << i;
        if (__builtin_popcountll(start) % 2) return -1;
        map<long long,long long> dist{{start, 0}};
        priority_queue<pair<long long,long long>, vector<pair<long long,long long>>, greater<>> pq;
        pq.push({0, start});
        while (!pq.empty()) {
            auto [c, m] = pq.top(); pq.pop();
            if (m == 0) return c;
            if (c > dist[m]) continue;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    long long nm = m ^ (1LL << i) ^ (1LL << j);
                    long long w = (j == i + 1) ? 1 : x;
                    if (!dist.count(nm) || c + w < dist[nm]) {
                        dist[nm] = c + w;
                        pq.push({c + w, nm});
                    }
                }
        }
        return -1;
    }
};

