import java.util.*;
class Solution {
    public int minOperations(String s1, String s2, int x) {
        int n = s1.length();
        if (n > 60) return -1; // bitmask brute force only feasible for tiny n
        long start = 0;
        for (int i = 0; i < n; i++) if (s1.charAt(i) != s2.charAt(i)) start |= 1L << i;
        if (Long.bitCount(start) % 2 == 1) return -1;
        Map<Long, Long> dist = new HashMap<>();
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        dist.put(start, 0L);
        pq.add(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long c = top[0], m = top[1];
            if (m == 0) return (int) c;
            if (c > dist.getOrDefault(m, Long.MAX_VALUE)) continue;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    long nm = m ^ (1L << i) ^ (1L << j);
                    long w = (j == i + 1) ? 1 : x;
                    if (c + w < dist.getOrDefault(nm, Long.MAX_VALUE)) {
                        dist.put(nm, c + w);
                        pq.add(new long[]{c + w, nm});
                    }
                }
        }
        return -1;
    }
}

