var minOperations = function(s1, s2, x) {
    const n = s1.length;
    if (n > 30) return -1; // bitmask brute force only feasible for tiny n
    let start = 0;
    for (let i = 0; i < n; i++) if (s1[i] !== s2[i]) start |= 1 << i;
    let pc = 0, t = start;
    while (t) { pc += t & 1; t >>= 1; }
    if (pc % 2) return -1;
    const dist = new Map([[start, 0]]);
    const pq = [[0, start]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [c, m] = pq.shift();
        if (m === 0) return c;
        if (c > dist.get(m)) continue;
        for (let i = 0; i < n; i++)
            for (let j = i + 1; j < n; j++) {
                const nm = m ^ (1 << i) ^ (1 << j);
                const w = j === i + 1 ? 1 : x;
                if (c + w < (dist.has(nm) ? dist.get(nm) : Infinity)) {
                    dist.set(nm, c + w);
                    pq.push([c + w, nm]);
                }
            }
    }
    return -1;
};

