        m = len(d)
        if m % 2:
            return -1
        INF = float('inf')
        none, pend = 0, [INF] * m
        for i in range(m):
            new_none = INF
            for k in range(i):
                if pend[k] < INF:
                    new_none = min(new_none, pend[k] + min(x, d[i] - d[k]))
            new_pend = pend[:]
            new_pend[i] = min(new_pend[i], none)
            none, pend = new_none, new_pend
        return none

