#include <vector>
#include <algorithm>
using namespace std;
class Solution {
public:
    int minOperations(string s1, string s2, int x) {
        vector<int> d;
        for (int i = 0; i < (int)s1.size(); i++)
            if (s1[i] != s2[i]) d.push_back(i);
        int m = d.size();
        if (m % 2) return -1;
        const long long INF = 1e18;
        long long none = 0;
        vector<long long> pend(m, INF);
        for (int i = 0; i < m; i++) {
            long long nn = INF;
            for (int k = 0; k < i; k++)
                if (pend[k] < INF)
                    nn = min(nn, pend[k] + min((long long)x, (long long)(d[i] - d[k])));
            vector<long long> np = pend;
            np[i] = min(np[i], none);
            none = nn;
            pend = move(np);
        }
        return (int)none;
    }
};

