class Solution {
    public int minOperations(String s1, String s2, int x) {
        java.util.List<Integer> dl = new java.util.ArrayList<>();
        for (int i = 0; i < s1.length(); i++)
            if (s1.charAt(i) != s2.charAt(i)) dl.add(i);
        int m = dl.size();
        if (m % 2 == 1) return -1;
        int[] d = new int[m];
        for (int i = 0; i < m; i++) d[i] = dl.get(i);
        final long INF = Long.MAX_VALUE / 4;
        long none = 0;
        long[] pend = new long[m];
        java.util.Arrays.fill(pend, INF);
        for (int i = 0; i < m; i++) {
            long nn = INF;
            for (int k = 0; k < i; k++)
                if (pend[k] < INF)
                    nn = Math.min(nn, pend[k] + Math.min(x, d[i] - d[k]));
            long[] np = pend.clone();
            np[i] = Math.min(np[i], none);
            none = nn;
            pend = np;
        }
        return (int) none;
    }
}

